style.css:
@-moz-document domain("pinterest.com") {
/* General font styling for the entire page */
    body, p, h1, h2, h3, span, div, a, button, input, textarea {
        font-family: "Courier New", Courier, monospace; /* Monospace aesthetic */
        color: #8c6e5b; /* Darker brown text */
    }

    /* Background color remains white */
    body {
        background-color: #ffffff;
    }

    /* Links */
    a {
        color: #8c6e5b; /* Darker brown for links */
        text-decoration: none;
    }
    a:hover {
        color: #755841; /* Slightly darker brown on hover */
    }

    /* Save button styles */
    button, .SaveButton, .saveButtonComponent, .button {
        background-color: #b39682; /* Soft brown */
        color: #ffffff; /* White text */
        font-family: "Courier New", monospace;
        border-radius: 5px;
        border: none;
        padding: 8px 12px;
        font-weight: bold;
        cursor: pointer;
        transition: background-color 0.3s, color 0.3s;
    }
    button:hover, .SaveButton:hover, .saveButtonComponent:hover, .button:hover {
        background-color: #8c6e5b; /* Darker brown on hover */
        color: #ffffff;
    }

    /* Side buttons and navigation */
    .sideBar button, .sideBar .navButton, .sideBar a {
        background-color: #b39682; /* Soft brown */
        color: #ffffff; /* White text */
        font-family: "Courier New", monospace;
        border-radius: 5px;
        padding: 8px;
        font-size: 14px;
        transition: background-color 0.3s;
    }
    .sideBar button:hover, .sideBar .navButton:hover, .sideBar a:hover {
        background-color: #8c6e5b; /* Darker brown on hover */
        color: #ffffff;
    }

    /* Comments section */
    .comments, .comment, .comment-text, .comment-input {
        color: #8c6e5b; /* Darker brown text */
        font-family: "Courier New", monospace;
        border: 1px solid #b39682; /* Soft brown border */
        background-color: #ffffff;
        transition: background-color 0.3s;
    }
    .comment-input:hover {
        background-color: #f1e6e1; /* Light brown on hover */
    }

    /* Search bar styling */
    input[type="text"], textarea {
        background-color: #ffffff; /* White background */
        color: #8c6e5b; /* Darker brown text */
        border: 1px solid #b39682; /* Soft brown border */
        font-family: "Courier New", monospace;
        padding: 5px 10px;
    }
    input[type="text"]::placeholder, textarea::placeholder {
        color: #d1b7a5; /* Softer brown */
    }
    input[type="text"]:hover, textarea:hover {
        border-color: #8c6e5b; /* Darker brown border on hover */
    }

    /* Pin descriptions and text */
    .gridCentered div div div > div {
        color: #8c6e5b; /* Darker brown text */
        font-family: "Courier New", monospace;
    }

    /* Hover effects for pins and other interactive elements */
    .gridCentered div:hover, button:hover, a:hover, .sideBar button:hover {
        background-color: #8c6e5b; /* Darker brown hover */
        color: #ffffff; /* White text */
        opacity: 0.9;
    }

    /* Footer (if visible) */
    footer {
        background-color: #ffffff;
        color: #8c6e5b; /* Darker brown text */
        font-family: "Courier New", monospace;
    }
}
